const tasks = $input.all();
const now = Date.now();

return tasks.map(item => {
  const task = item.json;

  const status = (task.status?.status || "").toLowerCase();

  const lastUpdated = Number(task.date_updated);
  const daysInactive = Number.isFinite(lastUpdated) && lastUpdated > 0
    ? Math.floor((now - lastUpdated) / (24 * 60 * 60 * 1000))
    : null;

  const completedStatuses = [
    "complete",
    "completed",
    "closed",
    "done"
  ];

  const isCompleted =
  completedStatuses.includes(status) ||
  task.status?.type === "closed" ||
  task.status?.type === "done";

  const isStalled =
    !isCompleted &&
    daysInactive !== null &&
    daysInactive >= 3;

  return {
    json: {
      task_id: task.id,
      task_name: task.name,
      status: status,
      days_inactive: daysInactive,
      is_stalled: isStalled,
      priority: task.priority?.priority || "normal",
      assignee: task.assignees?.map(a => a.username).join(", ") || "Unassigned",
      task_url: task.url
    }
  };
});

