const tasks = $input.all();
const now = Date.now();
const hours48 = 48 * 60 * 60 * 1000;

return tasks.map(item => {
  const task = item.json;

  const status = (task.status?.status || "").toLowerCase();
  const priority = task.priority?.priority?.toLowerCase() || "normal";
  const dueDate = task.due_date ? Number(task.due_date) : null;

  const isCompleted = ["complete", "completed", "closed", "cancelled"]
    .includes(status);

  const isOverdue = !isCompleted && dueDate !== null && dueDate < now;

  const dueSoon = !isCompleted &&
    dueDate !== null &&
    dueDate >= now &&
    dueDate <= now + hours48;

  const atRisk = ["at risk", "on hold", "update required"]
    .includes(status);

  let alertType = "Normal";

  if (isOverdue) {
    alertType = "Overdue";
  } else if (atRisk) {
    alertType = "At Risk";
  } else if (dueSoon) {
    alertType = "Due Soon";
  } else if (!isCompleted && ["high", "urgent"].includes(priority)) {
    alertType = "High Priority";
  }

  return {
    json: {
      task_id: task.id,
      task_name: task.name,
      status,
      priority,
      due_date: dueDate
        ? new Date(dueDate).toISOString()
        : null,
      assignee: task.assignees?.map(a => a.username).join(", ") || "Unassigned",
      alert_type: alertType,
      needs_attention: alertType !== "Normal",
      task_url: task.url || ""
    }
  };
});

const tasks = $input.all().map(item => item.json);

const formatDate = (date) => {
  if (!date) return "Not specified";
  const d = new Date(date);
  return isNaN(d.getTime())
    ? "Not specified"
    : d.toLocaleDateString("en-GB", {
        timeZone: "Africa/Lagos",
        day: "2-digit",
        month: "short",
        year: "numeric"
      });
};

const taskDetails = tasks.map((task, index) => {
  return `${index + 1}. ${task.task_name}
Priority: ${task.priority}
Due Date: ${formatDate(task.due_date)}
Assigned To: ${task.assignee || "Unassigned"}
Alert Type: ${task.alert_type}
Task Link: ${task.task_url || "Not available"}`;
}).join("\n\n");

const message = `🚨 CABINET PROJECT MANAGEMENT ALERT

Project: Modern Kitchen Cabinet Installation

Tasks Requiring Attention: ${tasks.length}

${taskDetails}

Please review these tasks and take appropriate action.

Generated automatically by the Cabinet Project Management AI Automation Engine.`;

return [{
  json: {
    project_name: "Modern Kitchen Cabinet Installation",
    total_alerts: tasks.length,
    alert_message: message,
    generated_at: new Date().toISOString()
  }
}];

const tasks = $input.all().map(item => item.json);

const now = Date.now();
const hours48 = 48 * 60 * 60 * 1000;

const completedStatuses = [
  "complete", "completed", "closed", "done", "cancelled"
];

let active = 0;
let completed = 0;
let overdue = 0;
let dueSoon = 0;
let highPriority = 0;
let atRisk = 0;

const attentionTasks = [];

for (const task of tasks) {
  const status = (task.status?.status || "").toLowerCase();
  const statusType = (task.status?.type || "").toLowerCase();
  const priority = (task.priority?.priority || "normal").toLowerCase();

  const dueDate = task.due_date
    ? Number(task.due_date)
    : null;

  const isCompleted =
    completedStatuses.includes(status) ||
    statusType === "closed" ||
    statusType === "done";

  if (isCompleted) {
    completed++;
    continue;
  }

  active++;

  const isOverdue = dueDate !== null && dueDate < now;
  const isDueSoon =
    dueDate !== null &&
    dueDate >= now &&
    dueDate <= now + hours48;

  const isHighPriority = ["high", "urgent"].includes(priority);
  const isAtRisk = ["at risk", "on hold", "update required"]
    .includes(status);

  if (isOverdue) overdue++;
  if (isDueSoon) dueSoon++;
  if (isHighPriority) highPriority++;
  if (isAtRisk) atRisk++;

  if (isOverdue || isDueSoon || isHighPriority || isAtRisk) {
    const reasons = [];

    if (isOverdue) reasons.push("Overdue");
    if (isDueSoon) reasons.push("Due Soon");
    if (isHighPriority) reasons.push("High Priority");
    if (isAtRisk) reasons.push("At Risk");

    attentionTasks.push(
      `• ${task.name}
  Assigned To: ${task.assignees?.map(a => a.username).join(", ") || "Unassigned"}
  Status: ${status}
  Attention: ${reasons.join(", ")}
  Link: ${task.url || "Not available"}`
    );
  }
}

const reportDate = new Date().toLocaleDateString("en-GB", {
  timeZone: "Africa/Lagos",
  day: "2-digit",
  month: "long",
  year: "numeric"
});

const report = `📋 DAILY CABINET PROJECT TEAM CHECK-IN

Date: ${reportDate}

📊 PROJECT OVERVIEW
Total Tasks: ${tasks.length}
Active Tasks: ${active}
Completed Tasks: ${completed}

⚠️ TASKS REQUIRING ATTENTION
Overdue: ${overdue}
Due Within 48 Hours: ${dueSoon}
High Priority: ${highPriority}
At Risk: ${atRisk}

📌 TASK DETAILS
${attentionTasks.length
  ? attentionTasks.join("\n\n")
  : "No tasks currently require attention."}

TEAM CHECK-IN QUESTIONS
1. What tasks did you complete?
2. What are you working on today?
3. Are there any blockers or delays?
4. Do you need assistance?

Please review your assigned tasks and provide updates.

Generated automatically by the Cabinet Project Management & AI Automation Engine.`;

return [{
  json: {
    report_date: reportDate,
    total_tasks: tasks.length,
    active_tasks: active,
    completed_tasks: completed,
    overdue_tasks: overdue,
    due_soon_tasks: dueSoon,
    high_priority_tasks: highPriority,
    at_risk_tasks: atRisk,
    report_message: report
  }
}];

const tasks = $input.all().map(item => item.json);
const now = new Date();

// Reporting period: Monday 00:00 to Friday 16:00,
// using the workflow timezone (Africa/Lagos).
const today = $now.setZone("Africa/Lagos");
const weekStart = today.startOf("week");
const weekEnd = today;

const completedStatuses = ["complete", "completed", "closed", "done"];

const isCompleted = task => {
  const status = (task.status?.status || "").toLowerCase();
  return completedStatuses.includes(status) ||
    task.status?.type === "closed" ||
    task.status?.type === "done";
};

const completedThisWeek = tasks.filter(task => {
  const completedAt = Number(task.date_closed || task.date_done);
  if (!isCompleted(task) || !completedAt) return false;

  return completedAt >= weekStart.toMillis() &&
         completedAt <= weekEnd.toMillis();
});

const activeTasks = tasks.filter(task => !isCompleted(task));

const overdueTasks = activeTasks.filter(task => {
  const due = Number(task.due_date);
  return due > 0 && due < now.getTime();
});

const highPriorityTasks = activeTasks.filter(task => {
  const priority = (task.priority?.priority || "").toLowerCase();
  return ["high", "urgent"].includes(priority);
});

const stalledTasks = activeTasks.filter(task => {
  const updated = Number(task.date_updated);
  return updated > 0 &&
    now.getTime() - updated >= 3 * 24 * 60 * 60 * 1000;
});

const formatTask = task => {
  const name = task.name || "Unnamed task";
  const assignee = task.assignees?.map(a => a.username).join(", ") || "Unassigned";
  return `- ${name} (Assigned to: ${assignee})`;
};

const report = [
  "WEEKLY CABINET PROJECT TEAM CHECK-IN",
  `Week beginning: ${weekStart.toFormat("dd LLL yyyy")}`,
  `Report generated: ${today.toFormat("dd LLL yyyy, h:mm a")}`,
  "",
  "PROJECT OVERVIEW",
  `Total tasks retrieved: ${tasks.length}`,
  `Active tasks: ${activeTasks.length}`,
  `Completed this week: ${completedThisWeek.length}`,
  `Overdue tasks: ${overdueTasks.length}`,
  `High-priority active tasks: ${highPriorityTasks.length}`,
  `Stalled tasks (3+ days inactive): ${stalledTasks.length}`,
  "",
  "COMPLETED THIS WEEK",
  ...(completedThisWeek.length
    ? completedThisWeek.map(formatTask)
    : ["No completed tasks recorded this week."]),
  "",
  "TASKS REQUIRING ATTENTION",
  ...(overdueTasks.length
    ? overdueTasks.map(formatTask)
    : ["No overdue tasks."]),
  "",
  "STALLED TASKS",
  ...(stalledTasks.length
    ? stalledTasks.map(formatTask)
    : ["No stalled tasks."]),
  "",
  "NEXT STEPS",
  "Review overdue and high-priority tasks.",
  "Follow up with owners of stalled tasks.",
  "Confirm priorities for the coming week."
].join("\n");

return [{
  json: {
    report_type: "weekly",
    report_date: today.toISODate(),
    total_tasks: tasks.length,
    active_tasks: activeTasks.length,
    completed_this_week: completedThisWeek.length,
    overdue_tasks: overdueTasks.length,
    high_priority_tasks: highPriorityTasks.length,
    stalled_tasks: stalledTasks.length,
    weekly_report: report
  }
}];
